CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS enquiries (id TEXT PRIMARY KEY, idempotency TEXT UNIQUE, received_at TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS attachments (id TEXT PRIMARY KEY, enquiry_id TEXT NOT NULL, filename TEXT NOT NULL, mime TEXT, bytes INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS attachment_chunks (attachment_id TEXT NOT NULL, part INTEGER NOT NULL, data BLOB NOT NULL, PRIMARY KEY(attachment_id,part));
CREATE TABLE IF NOT EXISTS rate_limits (ip TEXT PRIMARY KEY, minute INTEGER NOT NULL, count INTEGER NOT NULL);
